-- Pipeline Reliability 1.0.0 — consumer and agent grants
--
-- Every object is granted by name. GRANT ... ON ALL VIEWS would widen
-- the product silently the next time a view is added to the schema.
--
-- Consumers: ROLE_DATA_ENG, ROLE_PLATFORM_ENG
--
-- Generated by the Observability & FinOps Platform. Review before running.
-- The platform does not execute this script; a human does (R2, R8).

USE ROLE SECURITYADMIN;

GRANT USAGE ON DATABASE OBSERVABILITY TO ROLE SNOWOBS_CONSUMER;
GRANT USAGE ON SCHEMA OBSERVABILITY.PUBLISHED TO ROLE SNOWOBS_CONSUMER;
GRANT USAGE ON SCHEMA OBSERVABILITY.SEMANTIC TO ROLE SNOWOBS_CONSUMER;

GRANT SELECT ON VIEW OBSERVABILITY.PUBLISHED.V_PIPELINE_HEALTH_TASK_RUN TO ROLE SNOWOBS_CONSUMER;
GRANT SELECT ON VIEW OBSERVABILITY.PUBLISHED.V_PIPELINE_HEALTH_DYNAMIC_TABLE_REFRESH TO ROLE SNOWOBS_CONSUMER;

GRANT REFERENCES ON SEMANTIC VIEW OBSERVABILITY.SEMANTIC.PIPELINE_HEALTH TO ROLE SNOWOBS_CONSUMER;
GRANT REFERENCES ON SEMANTIC VIEW OBSERVABILITY.SEMANTIC.PIPELINE_HEALTH TO ROLE SNOWOBS_AGENT_USER;

GRANT USAGE ON CORTEX SEARCH SERVICE OBSERVABILITY.SEARCH.PIPELINE_HEALTH_TASK TO ROLE SNOWOBS_AGENT_USER;
GRANT USAGE ON AGENT OBSERVABILITY.AGENT.PIPELINE_HEALTH_AGENT TO ROLE SNOWOBS_AGENT_USER;
GRANT USAGE ON WAREHOUSE WH_SNOWOBS_AGENT TO ROLE SNOWOBS_AGENT_USER;

-- Grant the consumer role onward to the registered consumers. Each line is
-- one entry in the product's consumer register; adding a consumer is a
-- registry change, not an ad-hoc grant.
GRANT ROLE SNOWOBS_CONSUMER TO ROLE ROLE_DATA_ENG;  -- Data engineering on-call
GRANT ROLE SNOWOBS_CONSUMER TO ROLE ROLE_PLATFORM_ENG;  -- Platform reliability review

SHOW GRANTS TO ROLE SNOWOBS_CONSUMER;
